WITH gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) > INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_session FROM web_events), sessionized AS (SELECT id, session_id, event_time, duration_sec, SUM(is_new_session) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT id, event_time, duration_sec, island_id FROM sessionized
